118	// encodeFile 把内存状态编码为完整文件字节。
119	func encodeFile(st *mapState) ([]byte, error) {
120		fd := fileData{
121			Version:       int(fileVersion),
122			Config:        st.config,
123			Trajectory:    st.trajectory,
124			Landmarks:     make([]landmarkJSON, 0, len(st.landmarks)),
125			Segments:      make([]segmentJSON, 0, len(st.segments)),
126			Sources:       make([]*frameSrcJSON, len(st.sources)),
127			Corrections:   make([]corrRecJSON, 0, len(st.corrections)),
128			Invalidations: make([]invalJSON, 0, len(st.invalRecords)),
129		}
130		for id, lm := range st.landmarks {
131			lj := landmarkJSON{ID: id, Occurrences: make([]occurrenceJSON, 0, len(lm.appearances))}
132			for i, occ := range lm.appearances {
133				oj := occurrenceJSON{
134					Number:        i + 1,
135					X:             occ.x,
136					Y:             occ.y,
137					Count:         occ.count,
138					LegacyCount:   occ.legacyCount,
139					LegacyMX:      occ.legacyMX,
140					LegacyMY:      occ.legacyMY,
141					FirstSeenTime: occ.firstSeenTime,
142					HasFirstSeen:  occ.hasFirstSeen,
143					Active:        occ.active,
144				}
145				if !occ.active {
146					oj.InvalidTime = occ.invalidTime
147					oj.InvalidReason = occ.invalidReason
148					oj.InvalidOpID = occ.invalidOpID
149				}
150				lj.Occurrences = append(lj.Occurrences, oj)
151			}
152			fd.Landmarks = append(fd.Landmarks, lj)
153		}
154		for id, rec := range st.segments {
155			fd.Segments = append(fd.Segments, segmentJSON{ID: id, Hash: rec.hash, Result: rec.result})
156		}
157		for k, src := range st.sources {
158			if src == nil {
159				continue // 旧文件帧在新文件中保留为 null，表示仍无逐帧依据
160			}
161			obs := append([]Observation(nil), src.observations...)
162			fd.Sources[k] = &frameSrcJSON{MoveVariance: src.moveVariance, Observations: obs}
163		}
164		for _, rec := range st.corrections {
165			cj := corrRecJSON{
166				ID:        rec.ID,
167				Anchor:    rec.Anchor,
168				Target:    rec.Target,
169				EndTime:   rec.EndTime,
170				Poses:     make([]poseChangeJSON, len(rec.Poses)),
171				Landmarks: make([]landmarkChangeJSON, len(rec.Landmarks)),
172			}
173			for i, pc := range rec.Poses {
174				cj.Poses[i] = poseChangeJSON{Before: pc.Before, After: pc.After}
175			}
176			for i, lc := range rec.Landmarks {
177				cj.Landmarks[i] = landmarkChangeJSON{ID: lc.ID, Occurrence: lc.Occurrence, Before: lc.Before, After: lc.After}
178			}
179			fd.Corrections = append(fd.Corrections, cj)
180		}
181		for _, rec := range st.invalRecords {
182			ij := invalJSON{
183				ID:        rec.id,
184				Reason:    rec.reason,
185				Hash:      rec.hash,
186				Time:      rec.result.Time,
187				Landmarks: make([]invalLMJSON, len(rec.result.Landmarks)),
188			}
189			for i, l := range rec.result.Landmarks {
190				ij.Landmarks[i] = invalLMJSON{ID: l.ID, Occurrence: l.Occurrence}
191			}
192			fd.Invalidations = append(fd.Invalidations, ij)
193		}
194		payload, err := json.Marshal(&fd)
195		if err != nil {
196			return nil, fmt.Errorf("posemap: encode state: %w", err)
197		}
198	
199		out := make([]byte, headerLen+len(payload)+4)
200		copy(out[0:8], fileMagic)
201		binary.BigEndian.PutUint16(out[8:10], fileVersion)
202		binary.BigEndian.PutUint32(out[10:14], uint32(len(payload)))
203		copy(out[headerLen:], payload)
204		sum := crc32.ChecksumIEEE(out[:headerLen+len(payload)])
205		binary.BigEndian.PutUint32(out[headerLen+len(payload):], sum)
206		return out, nil
207	}
208	
209	// loadFile 只读取证地解析地图文件。
210	func loadFile(path string) (*mapState, error) {
211		raw, err := os.ReadFile(path)
212		if err != nil {
213			return nil, err // 含 fs.ErrNotExist，交由调用方/上层用 errors.Is 判断
214		}
215		if len(raw) < headerLen+4 || string(raw[:8]) != fileMagic {
216			return nil, fmt.Errorf("%w: unrecognized header", ErrCorrupt)
217		}
218		version := binary.BigEndian.Uint16(raw[8:10])
219		if version != fileVersion {
220			return nil, fmt.Errorf("%w: version %d", ErrUnsupportedVersion, version)
221		}
222		length := binary.BigEndian.Uint32(raw[10:14])
223		if int(length) != len(raw)-headerLen-4 {
224			return nil, fmt.Errorf("%w: truncated or length mismatch", ErrCorrupt)
225		}
226		want := binary.BigEndian.Uint32(raw[len(raw)-4:])
227		if crc32.ChecksumIEEE(raw[:len(raw)-4]) != want {
228			return nil, fmt.Errorf("%w: checksum mismatch", ErrCorrupt)
229		}
230	
231		var fd fileData
232		if err := json.Unmarshal(raw[headerLen:headerLen+int(length)], &fd); err != nil {
233			return nil, fmt.Errorf("%w: %v", ErrCorrupt, err)
234		}
235		if err := validateLoaded(&fd); err != nil {
236			return nil, err
237		}
238	
239		st := &mapState{
240			config:       fd.Config,
241			trajectory:   fd.Trajectory,
242			landmarks:    make(map[string]*landmarkState, len(fd.Landmarks)),
243			segments:     make(map[string]*segmentRecord, len(fd.Segments)),
244			sources:      make([]*frameSource, len(fd.Trajectory)-1),
245			corrections:  make([]*CorrectionRecord, 0, len(fd.Corrections)),
246			corrIndex:    make(map[string]string, len(fd.Corrections)),
247			invalRecords: make([]*invalidationRecord, 0, len(fd.Invalidations)),
248			invalIndex:   make(map[string]*invalidationRecord, len(fd.Invalidations)),
249		}
250		// 旧文件不携带逐帧依据：有帧而 sources 缺省即旧地图。无帧时二者
251		// 无法区分也无需区分（尚无范围可校正）。
252		oldFormat := len(fd.Sources) == 0 && len(fd.Trajectory) > 1
253		for _, lmj := range fd.Landmarks {
254			lm := &landmarkState{}
255			if len(lmj.Occurrences) > 0 {
256				// 新格式：历次出现按编号递增保存。
257				for _, oj := range lmj.Occurrences {
258					lm.appearances = append(lm.appearances, &occurrenceState{
259						x:             oj.X,
260						y:             oj.Y,
261						count:         oj.Count,
262						legacyCount:   oj.LegacyCount,
263						legacyMX:      oj.LegacyMX,
264						legacyMY:      oj.LegacyMY,
265						firstSeenTime: oj.FirstSeenTime,
266						hasFirstSeen:  oj.HasFirstSeen,
267						active:        oj.Active,
268						invalidTime:   oj.InvalidTime,
269						invalidReason: oj.InvalidReason,
270						invalidOpID:   oj.InvalidOpID,
271					})
272				}
273			} else {
274				// 兼容旧布局：一个平铺路标即第 1 次有效出现。
275				occ := &occurrenceState{
276					x:      lmj.X,
277					y:      lmj.Y,
278					count:  lmj.Count,
279					active: true,
280				}
281				if oldFormat {
282					// 旧文件中该路标的全部既有观测都是固定旧贡献，位置取
283					// 文件中的聚合值；缺少逐帧来源，首次观测时间未知。
284					occ.legacyCount = lmj.Count
285					occ.legacyMX, occ.legacyMY = lmj.X, lmj.Y
286					occ.hasFirstSeen = false
287				} else {
288					occ.legacyCount = lmj.LegacyCount
289					occ.legacyMX, occ.legacyMY = lmj.LegacyMX, lmj.LegacyMY
290					// 含固定旧贡献时最早观测缺少来源，首次观测时间未知；
291					// 否则从逐帧依据中恢复该出现第一次被观测到的帧时间。
292					occ.hasFirstSeen = lmj.LegacyCount == 0
293					if occ.hasFirstSeen {
294						for k, src := range fd.Sources {
295							if src == nil {
296								continue
297							}
298							found := false
299							for _, ob := range src.Observations {
300								if ob.ID == lmj.ID {
301									found = true
302									break
303								}
304							}
305							if found {
306								occ.firstSeenTime = fd.Trajectory[k+1].Time
307								break
308							}
309						}
310					}
311				}
312				lm.appearances = append(lm.appearances, occ)
313			}
314			st.landmarks[lmj.ID] = lm
315		}
316		for _, sg := range fd.Segments {
317			ids := sg.Result.LandmarkIDs
318			if ids == nil {
319				ids = []string{}
320			}
321			st.segments[sg.ID] = &segmentRecord{
322				hash:   sg.Hash,
323				result: ImportResult{EndPose: sg.Result.EndPose, LandmarkIDs: ids},
324			}
325		}
326		if !oldFormat {
327			for k, src := range fd.Sources {
328				if src == nil {
329					continue // 来自旧文件的帧：保持依据缺失
330				}
331				obs := append([]Observation(nil), src.Observations...)
332				st.sources[k] = &frameSource{moveVariance: src.MoveVariance, observations: obs}
333			}
334		}
335		for _, cj := range fd.Corrections {
336			rec := &CorrectionRecord{
337				ID:        cj.ID,
338				Anchor:    cj.Anchor,
339				Target:    cj.Target,
340				EndTime:   cj.EndTime,
341				Poses:     make([]PoseChange, len(cj.Poses)),
342				Landmarks: make([]LandmarkChange, len(cj.Landmarks)),
343			}
344			for i, pc := range cj.Poses {
345				rec.Poses[i] = PoseChange{Before: pc.Before, After: pc.After}
346			}
347			for i, lc := range cj.Landmarks {
348				occNum := lc.Occurrence
349				if occNum == 0 {
350					occNum = 1 // 更早版本写出的校正记录不带编号，只有第 1 次出现
351				}
352				rec.Landmarks[i] = LandmarkChange{ID: lc.ID, Occurrence: occNum, Before: lc.Before, After: lc.After}
353			}
354			st.corrections = append(st.corrections, rec)
355			st.corrIndex[cj.ID] = canonicalCorrectionHash(cj.Anchor, cj.Target)
356		}
357		for _, ij := range fd.Invalidations {
358			lms := make([]InvalidatedLandmark, len(ij.Landmarks))
359			for i, l := range ij.Landmarks {
360				lms[i] = InvalidatedLandmark{ID: l.ID, Occurrence: l.Occurrence}
361			}
362			rec := &invalidationRecord{
363				id:     ij.ID,
364				reason: ij.Reason,
365				hash:   ij.Hash,
366				result: InvalidationResult{Time: ij.Time, Landmarks: lms},
367			}
368			st.invalRecords = append(st.invalRecords, rec)
369			st.invalIndex[ij.ID] = rec
370		}
371		return st, nil
372	}
373	
374	// validateLoaded 对解码后的状态做基本不变量检查，违背即视为损坏。
375	func validateLoaded(fd *fileData) error {
376		switch {
377		case fd.Version != int(fileVersion):
378			return fmt.Errorf("%w: version %d in payload", ErrUnsupportedVersion, fd.Version)
379		case len(fd.Trajectory) == 0:
380			return fmt.Errorf("%w: empty trajectory", ErrCorrupt)
381		}
382		if err := validateConfig(fd.Config); err != nil {
383			// 配置不合法不可能由本版本写出。
384			return fmt.Errorf("%w: %v", ErrCorrupt, err)
385		}
386		// 新格式的逐帧依据必须与轨迹（除初始位姿外）一一对应；旧文件缺省
387		// 该字段（解码为 nil），数量为 0。
388		if len(fd.Sources) != 0 && len(fd.Sources) != len(fd.Trajectory)-1 {
389			return fmt.Errorf("%w: frame sources length %d for %d frames", ErrCorrupt, len(fd.Sources), len(fd.Trajectory)-1)
390		}
391		timeAt := func(t int64) bool {
392			for _, p := range fd.Trajectory {
393				if p.Time == t {
394					return true
395				}
396			}
397			return false
398		}
399		seenIDs := make(map[string]struct{}, len(fd.Landmarks))
400		for _, lm := range fd.Landmarks {
401			if lm.ID == "" {
402				return fmt.Errorf("%w: invalid landmark record", ErrCorrupt)
403			}
404			if _, dup := seenIDs[lm.ID]; dup {
405				return fmt.Errorf("%w: duplicate landmark %s", ErrCorrupt, lm.ID)
406			}
407			seenIDs[lm.ID] = struct{}{}
408			if len(lm.Occurrences) == 0 {
409				// 兼容旧布局：平铺字段表示第 1 次出现。
410				if lm.Count < 1 || !isFinite(lm.X) || !isFinite(lm.Y) {
411					return fmt.Errorf("%w: invalid landmark record", ErrCorrupt)
412				}
413				if lm.LegacyCount < 0 || lm.LegacyCount > lm.Count {
414					return fmt.Errorf("%w: invalid legacy count for landmark %s", ErrCorrupt, lm.ID)
415				}
416				if lm.LegacyCount > 0 && (!isFinite(lm.LegacyMX) || !isFinite(lm.LegacyMY)) {
417					return fmt.Errorf("%w: invalid legacy mean for landmark %s", ErrCorrupt, lm.ID)
418				}
419				continue
420			}
421			activeCount := 0
422			for i, oj := range lm.Occurrences {
423				if oj.Number != i+1 || oj.Count < 1 || !isFinite(oj.X) || !isFinite(oj.Y) {
424					return fmt.Errorf("%w: invalid occurrence for landmark %s", ErrCorrupt, lm.ID)
425				}
426				if oj.LegacyCount < 0 || oj.LegacyCount > oj.Count {
427					return fmt.Errorf("%w: invalid legacy count for landmark %s occurrence %d", ErrCorrupt, lm.ID, oj.Number)
428				}
429				if oj.LegacyCount > 0 && (!isFinite(oj.LegacyMX) || !isFinite(oj.LegacyMY)) {
430					return fmt.Errorf("%w: invalid legacy mean for landmark %s occurrence %d", ErrCorrupt, lm.ID, oj.Number)
431				}
432				if oj.Active {
433					activeCount++
434					if i != len(lm.Occurrences)-1 {
435						return fmt.Errorf("%w: active occurrence %d of landmark %s is not the latest", ErrCorrupt, oj.Number, lm.ID)
436					}
437				} else if oj.InvalidReason == "" {
438					return fmt.Errorf("%w: invalidated occurrence %d of landmark %s lacks reason", ErrCorrupt, oj.Number, lm.ID)
439				}
440			}
441			if activeCount > 1 {
442				return fmt.Errorf("%w: multiple active occurrences for landmark %s", ErrCorrupt, lm.ID)
443			}
444		}
445		segIDs := make(map[string]struct{}, len(fd.Segments))
446		for _, sg := range fd.Segments {
447			if sg.ID == "" || sg.Hash == "" {
448				return fmt.Errorf("%w: invalid segment record", ErrCorrupt)
449			}
450			if _, dup := segIDs[sg.ID]; dup {
451				return fmt.Errorf("%w: duplicate segment %s", ErrCorrupt, sg.ID)
452			}
453			segIDs[sg.ID] = struct{}{}
454		}
455		corrIDs := make(map[string]struct{}, len(fd.Corrections))
456		for _, cr := range fd.Corrections {
457			if cr.ID == "" || !timeAt(cr.Anchor) || !timeAt(cr.EndTime) || cr.Anchor > cr.EndTime {
458				return fmt.Errorf("%w: invalid correction record", ErrCorrupt)
459			}
460			if len(cr.Poses) == 0 {
461				return fmt.Errorf("%w: correction %s has no affected poses", ErrCorrupt, cr.ID)
462			}
463			for _, pc := range cr.Poses {
464				if !finitePose(pc.Before) || !finitePose(pc.After) {
465					return fmt.Errorf("%w: correction %s has non-finite pose", ErrCorrupt, cr.ID)
466				}
467			}
468			for _, lc := range cr.Landmarks {
469				if lc.ID == "" {
470					return fmt.Errorf("%w: correction %s has empty landmark id", ErrCorrupt, cr.ID)
471				}
472				if lc.Occurrence < 0 || !isFinite(lc.Before.X) || !isFinite(lc.Before.Y) ||
473					!isFinite(lc.After.X) || !isFinite(lc.After.Y) ||
474					lc.Before.Count < 1 || lc.After.Count < 1 {
475					return fmt.Errorf("%w: correction %s has invalid landmark change", ErrCorrupt, cr.ID)
476				}
477			}
478			if _, dup := corrIDs[cr.ID]; dup {
479				return fmt.Errorf("%w: duplicate correction %s", ErrCorrupt, cr.ID)
480			}
481			corrIDs[cr.ID] = struct{}{}
482		}
483		invalIDs := make(map[string]struct{}, len(fd.Invalidations))
484		for _, iv := range fd.Invalidations {
485			if iv.ID == "" || iv.Reason == "" || iv.Hash == "" || len(iv.Landmarks) == 0 {
486				return fmt.Errorf("%w: invalid invalidation record", ErrCorrupt)
487			}
488			if _, dup := invalIDs[iv.ID]; dup {
489				return fmt.Errorf("%w: duplicate invalidation %s", ErrCorrupt, iv.ID)
490			}
491			invalIDs[iv.ID] = struct{}{}
492			lmSeen := make(map[string]struct{}, len(iv.Landmarks))
493			for _, l := range iv.Landmarks {
494				if l.ID == "" || l.Occurrence < 1 {
495					return fmt.Errorf("%w: invalid invalidation landmark entry", ErrCorrupt)
496				}
497				if _, dup := lmSeen[l.ID]; dup {
498					return fmt.Errorf("%w: invalidation %s lists %s twice", ErrCorrupt, iv.ID, l.ID)
499				}
500				lmSeen[l.ID] = struct{}{}
501			}
502		}
503		return nil
504	}
505	
506	func finitePose(p Pose) bool {
507		return isFinite(p.X) && isFinite(p.Y) && isFinite(p.Heading) && isFinite(p.Variance)
508	}
509	
510	// canonicalCorrectionHash 计算一次校正请求（锚点时间 + 目标位姿）的
511	// 确定性指纹，用于同标识重复提交判定。直接按 IEEE-754 位编码。
512	func canonicalCorrectionHash(anchor int64, tgt CorrectionTarget) string {
513		h := sha256.New()
514		var b [8]byte
515		binary.BigEndian.PutUint64(b[:], uint64(anchor))
516		h.Write(b[:])
517		for _, v := range []float64{tgt.X, tgt.Y, tgt.Heading, tgt.Variance} {
518			binary.BigEndian.PutUint64(b[:], math.Float64bits(v))
519			h.Write(b[:])
520		}
521		return fmt.Sprintf("%x", h.Sum(nil))
522	}
523	
524	// saveExclusive 创建新文件，目标已存在即失败（O_EXCL）。
525	func (m *Map) saveExclusive() error {
526		data, err := encodeFile(m.state)
527		if err != nil {
528			return err
529		}
530		f, err := os.OpenFile(m.path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o644)
531		if err != nil {
532			return err
533		}
534		return writeAndClose(f, data, m.path)
535	}
536	
537	// saveReplace 用同目录临时文件 + rename 原子替换现有文件。
538	func (m *Map) saveReplace() (err error) {
539		data, err := encodeFile(m.state)
540		if err != nil {
541			return err
542		}
543		dir, base := filepath.Split(m.path)
544		if dir == "" {
545			dir = "."
546		}
547		f, err := os.CreateTemp(dir, base+".tmp-*")
548		if err != nil {
549			return err
550		}
551		tmpName := f.Name()
552		// 任何失败路径都尽力清理临时文件。
553		defer func() {
554			if err != nil {
555				_ = os.Remove(tmpName)
556			}
557		}()
558		if err = writeAndClose(f, data, tmpName); err != nil {
559			return err
560		}
561		if err = os.Rename(tmpName, m.path); err != nil {
562			return err
563		}
564		return nil
565	}
566	
567	func writeAndClose(f *os.File, data []byte, name string) (err error) {
568		defer func() {
569			if cerr := f.Close(); err == nil {
570				err = cerr
571			}
572		}()
573		if _, err = f.Write(data); err != nil {
574			return err
575		}
576		if err = f.Sync(); err != nil {
577			return err
578		}
579		return nil
580	}
581	
582	// canonicalHash 计算一批帧的确定性指纹，用于重复导入判定。直接按
583	// IEEE-754 位编码，NaN/Inf 也有稳定表示，不依赖 JSON 对其不支持的问题。
584	func canonicalHash(frames []Frame) string {
585		h := sha256.New()
586		var lenBuf [4]byte
587		var numBuf [8]byte
588		putU32 := func(v uint32) {
589			binary.BigEndian.PutUint32(lenBuf[:], v)
590			h.Write(lenBuf[:])
591		}
592		putU64 := func(v uint64) {
593			binary.BigEndian.PutUint64(numBuf[:], v)
594			h.Write(numBuf[:])
595		}
596		putStr := func(s string) {
597			putU32(uint32(len(s)))
598			h.Write([]byte(s))
599		}
600	
601		putU32(uint32(len(frames)))
602		for _, fr := range frames {
603			putU64(uint64(fr.Time))
604			putU64(math.Float64bits(fr.DX))
605			putU64(math.Float64bits(fr.DY))
606			putU64(math.Float64bits(fr.DHeading))
607			putU64(math.Float64bits(fr.MoveVariance))
608			putU32(uint32(len(fr.Observations)))
609			for _, ob := range fr.Observations {
610				putStr(ob.ID)
611				putU64(math.Float64bits(ob.X))
612				putU64(math.Float64bits(ob.Y))
613			}
614		}
615		return fmt.Sprintf("%x", h.Sum(nil))
616	}
617

