13	func approxEq(t *testing.T, name string, got, want float64) {
14		t.Helper()
15		if math.IsNaN(want) {
16			if !math.IsNaN(got) {
17				t.Fatalf("%s = %v, want NaN", name, got)
18			}
19			return
20		}
21		if math.Abs(got-want) > 1e-10 {
22			t.Fatalf("%s = %v, want %v", name, got, want)
23		}
24	}
