26	func baseConfig() Config {
27		return Config{
28			InitialTime:     0,
29			InitialX:        1,
30			InitialY:        2,
31			InitialHeading:  0,
32			InitialVariance: 0.5,
33			MaxInterval:     1000,
34			MergeDistance:   1.0,
35		}
