38	func newMap(t *testing.T, cfg Config) *Map {
39		t.Helper()
40		m, err := Create(filepath.Join(t.TempDir(), "map.pose"), cfg)
41		if err != nil {
42			t.Fatalf("Create: %v", err)
43		}
44		t.Cleanup(func() { _ = m.Close() })
45		return m
46	}
