48	func TestInvalidConfig(t *testing.T) {
49		dir := t.TempDir()
50		cases := []Config{
51			baseConfig(),
52		}
53		{
54			c := baseConfig()
55			c.MaxInterval = 0
56			cases = append(cases, c)
57		}
58		{
59			c := baseConfig()
60			c.MaxInterval = -1
61			cases = append(cases, c)
62		}
