64			c := baseConfig()
65			c.MergeDistance = 0
66			cases = append(cases, c)
67		}
68		{
69			c := baseConfig()
70			c.MergeDistance = -2
71			cases = append(cases, c)
72		}
73		{
74			c := baseConfig()
75			c.InitialVariance = -0.1
76			cases = append(cases, c)
77		}
