237				{Time: 1102}, // 1102-100 = 1002 > 1000
238			}}, RejectInterval, 0, ""},
239			{"interval exceeded later frame", Segment{ID: "x", Frames: []Frame{
240				{Time: 101}, {Time: 1103},
241			}}, RejectInterval, 1, ""},
242			{"landmark conflict", Segment{ID: "x", Frames: []Frame{
243				{Time: 101, Observations: []Observation{{ID: "K", X: 10, Y: 10}}},
244			}}, RejectLandmarkConflict, 0, "K"},
245		}
246		for _, c := range cases {
247			t.Run(c.name, func(t *testing.T) {
248				_, err := m.ImportSegment(c.seg)
249				if err == nil {
250					t.Fatal("expected rejection")
251				}
252				if c.frame >= 0 {
253					rejectKind(t, err, c.kind, c.frame, c.landmark)
254				} else {
255					r, ok := AsRejectError(err)
256					if !ok || r.Kind != c.kind {
257						t.Fatalf("kind = %v, want %s", err, c.kind)
258					}
259				}
260			})
261		}
262	
263		// 全部失败后状态仍是 good 段之后：位姿、路标、次数均不变。
264		cur, _ := m.CurrentPose()
265		if cur.Time != 100 {
266			t.Fatalf("current time = %d, state leaked after rejection", cur.Time)
267		}
268		approxEq(t, "variance unchanged", cur.Variance, 0.6)
269		lms, _ := m.LandmarksInRect(Rect{MinX: -1e9, MinY: -1e9, MaxX: 1e9, MaxY: 1e9})
270		if len(lms) != 1 || lms[0].ID != "K" || lms[0].Count != 1 {
271			t.Fatalf("landmarks leaked: %v", lms)
272		}
273	
274		// 边界：间隔恰为上限可接受；路标距离恰为合并距离可接受。
275		if _, err := m.ImportSegment(Segment{ID: "bound", Frames: []Frame{
276			{Time: 1100, Observations: []Observation{{ID: "K", X: 1, Y: 0}}}, // 世界 (3,2)，距 K(2,2)=1
277		}}); err != nil {
278			t.Fatalf("boundary case rejected: %v", err)
279		}
280		lms, _ = m.LandmarksInRect(Rect{MinX: -1e9, MinY: -1e9, MaxX: 1e9, MaxY: 1e9})
281		for _, lm := range lms {
282			if lm.ID == "K" && lm.Count != 2 {
